1	package app
2	
3	import (
4		"context"
5		"log"
6		"strings"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/command"
11		"github.com/anthnel/devdesk/internal/config"
12		"github.com/anthnel/devdesk/internal/credentials"
13		"github.com/anthnel/devdesk/internal/forge"
14		"github.com/anthnel/devdesk/internal/forge/session"
15		"github.com/anthnel/devdesk/internal/ui/theme"
16	)
17	
18	// ContextSwitchCompleteMsg reports the success of a context switch
19	type ContextSwitchCompleteMsg struct {
20		ContextName string
21		Config      *config.Config
22		Created     bool // true if the context was created automatically
23		Forge       forge.Forge
24		GitLabUser  forge.User
25	
26		// Secrets is the store resolved for the new context, and Notices what the
27		// migration off plaintext had to say. Both are carried in the message
28		// rather than assigned by the Cmd that built them (Rule 110).
29		Secrets credentials.Selection
30		Notices []string
31	}
32	
33	// ContextSwitchErrorMsg reports an error during the switch
34	type ContextSwitchErrorMsg struct {
35		Error error
36	}
37	
38	// ContextListMsg holds the list of available contexts
39	type ContextListMsg struct {
40		Contexts []string
41		Current  string
42	}
43	
44	// switchContext handles context switching with auto-creation.
45	//
46	// It settles the current view first, for the reason switchView does: a context
47	// switch rebuilds every view against a different file, so an uncommitted edit
48	// would be dropped — and dropped against the config it was *not* meant for.
49	func (a *App) switchContext(contextName string) tea.Cmd {
50		if cmd, ok := a.settleCurrentView(); !ok {
51			return cmd
52		}
53		a.switchingTo = contextName
54	
55		return func() tea.Msg {
56			log.Printf("Context switch requested: %s", contextName)
57	
58			cfg, created, err := loadOrCreateContext(contextName)
59			if err != nil {
60				return ContextSwitchErrorMsg{Error: err}
61			}
62	
63			// Each context gets its own store: the backend preference is per
64			// context because the configuration file is, and the secrets are keyed
65			// by context so two of them pointing at the same host stay separate.
66			secrets := credentials.Select(contextName, cfg.App.SecretBackend)
67			notices := credentials.MigrateLegacySecrets(secrets.Storage, contextName)
68	
69			backend, user := autoLoginForContext(contextName, cfg, secrets.Storage)
70	
71			log.Printf("Context switch successful: %s (created: %v, secrets: %s)", contextName, created, secrets.Backend)
72			return ContextSwitchCompleteMsg{
73				ContextName: contextName,
74				Config:      cfg,
75				Created:     created,
76				Forge:       backend,
77				GitLabUser:  user,
78				Secrets:     secrets,
79				Notices:     notices,
80			}
81		}
82	}
83	
84	// loadOrCreateContext validates the name, creates the context when it does not
85	// exist yet, loads its configuration and persists it as current.
86	func loadOrCreateContext(contextName string) (*config.Config, bool, error) {
87		if err := config.ValidateContextName(contextName); err != nil {
88			log.Printf("ERROR: Context validation failed: %v", err)
89			return nil, false, err
90		}
91	
92		exists, err := config.ContextExists(contextName)
93		if err != nil {
94			log.Printf("ERROR: Failed to check context existence: %v", err)
95			return nil, false, err
96		}
97	
98		created := false
