120		return cfg, created, nil
121	}
122	
123	// autoLoginForContext tries the new context's own credentials. A failure is not
124	// an error: the user is sent to the auth view instead.
125	func autoLoginForContext(contextName string, cfg *config.Config, storage credentials.Storage) (forge.Forge, forge.User) {
126		if cfg.Forge.URL == "" {
127			return nil, forge.User{}
