146	// listContexts retrieves available contexts
147	func (a *App) listContexts() tea.Cmd {
148		return func() tea.Msg {
149			log.Printf("Listing available contexts")
150			contexts, err := config.ListContexts()
151			if err != nil {
152				log.Printf("ERROR: Failed to list contexts: %v", err)
153				return ContextSwitchErrorMsg{Error: err}
154			}
