1	package app
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/anthnel/devdesk/internal/command"
8		"github.com/anthnel/devdesk/internal/ui/cmdsuggest"
9	)
10	
11	// minListHeight is the smallest usable viewport height that holds a list: one
12	// row and the bottom rule.
13	const minListHeight = 2
14	
15	// noticeEmptyLine is the warning for an enter on a line with nothing typed.
16	const noticeEmptyLine = "Type a name or choose one"
17	
18	// refreshSuggestions ranks the registry for the text in the command line. The
19	// first row is highlighted when a query is typed (a bare ":" is none) and
20	// something is found; otherwise nothing is, so enter cannot run a command nobody chose.
21	func (a *App) refreshSuggestions() {
22		a.suggestions = a.suggester.Suggest(a.commandInput.Value())
23		a.sugOffset = 0
24		a.sugCursor = -1
25		if a.suggestions.Query != "" && len(a.suggestions.Entries) > 0 {
26			a.sugCursor = 0
27		}
28	}
29	
30	// resetSuggestions forgets the list; the command line is closed or about to be
31	// reopened empty.
32	func (a *App) resetSuggestions() {
33		a.suggestions = command.Suggestions{}
34		a.sugCursor = -1
35		a.sugOffset = 0
36		a.sugNotice = ""
37	}
38	
39	// highlightedEntry returns the highlighted row, if there is one. With no list
40	// drawn there is no highlight: a choice nobody can see is never made.
41	func (a *App) highlightedEntry() (command.Entry, bool) {
42		if a.listVisible() == 0 || a.sugCursor < 0 || a.sugCursor >= len(a.suggestions.Entries) {
43			return command.Entry{}, false
44		}
45		return a.suggestions.Entries[a.sugCursor], true
46	}
47	
48	// canComplete reports whether tab has something to complete: a highlighted
49	// row, at the command stage (an argument is typed, not chosen).
50	func (a *App) canComplete() bool {
51		_, ok := a.highlightedEntry()
52		return ok && a.suggestions.Stage == command.StageCommand
53	}
54	
55	// nothingToRunNotice is the warning for an enter with no highlighted row.
56	func (a *App) nothingToRunNotice() string {
57		q := a.suggestions.Query
58		if q == "" {
59			return noticeEmptyLine
60		}
61		return fmt.Sprintf("%q is not a view or a command", q)
62	}
63	
64	// completeHighlighted writes the highlighted row's name into the line, with a
65	// trailing space when the command takes an argument. It runs nothing.
66	func (a *App) completeHighlighted() {
67		if !a.canComplete() {
68			return
69		}
70		entry, _ := a.highlightedEntry()
71		text := entry.Name
72		if entry.TakesArg() {
73			text += " "
74		}
75		a.commandInput.SetValue(text)
76		a.commandInput.CursorEnd()
77		a.refreshSuggestions()
78	}
79	
80	// listUsable is the number of viewport content lines the list may cover.
81	func (a *App) listUsable() int {
82		if a.frameless() {
83			return a.viewport.Height
84		}
85		return a.viewport.Height - 1 // the bottom border stays
86	}
87	
88	// listVisible is how many suggestion rows are drawn; 0 means no list.
89	func (a *App) listVisible() int {
90		usable := a.listUsable()
91		if usable < minListHeight {
92			return 0
93		}
94		return cmdsuggest.VisibleRows(len(a.suggestions.Entries), usable)
95	}
96	
97	// moveHighlight moves the highlight by delta rows without wrapping. With no
98	// highlighted row, down takes the first visible row and up the last.
99	func (a *App) moveHighlight(delta int) {
100		n := len(a.suggestions.Entries)
101		if n == 0 {
102			return
103		}
104		visible := a.listVisible()
105		switch {
106		case a.sugCursor < 0 && delta > 0:
107			a.sugCursor = a.sugOffset
108		case a.sugCursor < 0:
109			a.sugCursor = min(n-1, a.sugOffset+max(visible, 1)-1)
110		default:
111			a.sugCursor = max(min(a.sugCursor+delta, n-1), 0)
112		}
113		a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, visible)
114	}
115	
116	// keepHighlightVisible re-windows the list after the viewport changed size.
117	func (a *App) keepHighlightVisible() {
118		a.sugOffset = cmdsuggest.Window(a.sugCursor, a.sugOffset, a.listVisible())
119	}
120	
121	// suggestionLines renders the list and its bottom rule, or nil when the command
122	// line is closed or the viewport is too short for a list.
123	func (a *App) suggestionLines() []string {
124		visible := a.listVisible()
125		if !a.commandMode || visible == 0 {
126			return nil
127		}
128		rows := make([]cmdsuggest.Row, len(a.suggestions.Entries))
129		for i, e := range a.suggestions.Entries {
130			rows[i] = cmdsuggest.Row{Entry: e, Current: e.Kind == command.KindView && e.Name == string(a.currentView)}
131		}
132		frame := cmdsuggest.FrameJoined
133		if a.frameless() {
134			frame = cmdsuggest.FrameClosed
135		}
136		return cmdsuggest.Render(cmdsuggest.Input{
137			Rows:    rows,
138			Total:   a.suggestions.Total,
139			Query:   a.suggestions.Query,
140			Cursor:  a.sugCursor,
141			Offset:  a.sugOffset,
142			Notice:  a.sugNotice,
143			Width:   a.viewport.Width,
144			Visible: visible,
145			Frame:   frame,
146		})
147	}
148	
149	// overlaySuggestions replaces the top lines of the viewport with the list.
150	// Whole lines are swapped, so no styled text is ever cut.
151	func (a *App) overlaySuggestions(body string) string {
152		list := a.suggestionLines()
153		if len(list) == 0 {
154			return body
155		}
156		lines := strings.Split(body, "\n")
157		copy(lines, list)
158		return strings.Join(lines, "\n")
159	}
