1	package app
2	
3	import (
4		"context"
5		"log"
6		"strings"
7	
8		tea "github.com/charmbracelet/bubbletea"
9	
10		"github.com/anthnel/devdesk/internal/command"
11		"github.com/anthnel/devdesk/internal/config"
12		"github.com/anthnel/devdesk/internal/credentials"
13		"github.com/anthnel/devdesk/internal/forge"
14		"github.com/anthnel/devdesk/internal/forge/session"
15		"github.com/anthnel/devdesk/internal/ui/theme"
16	)
17	
18	// ContextSwitchCompleteMsg reports the success of a context switch
19	type ContextSwitchCompleteMsg struct {
20		ContextName string
21		Config      *config.Config
22		Created     bool // true if the context was created automatically
23		Forge       forge.Forge
24		GitLabUser  forge.User
25	
26		// Secrets is the store resolved for the new context, and Notices what the
27		// migration off plaintext had to say. Both are carried in the message
28		// rather than assigned by the Cmd that built them (Rule 110).
29		Secrets credentials.Selection
30		Notices []string
31	}
32	
33	// ContextSwitchErrorMsg reports an error during the switch
34	type ContextSwitchErrorMsg struct {
35		Error error
36	}
37	
38	// ContextListMsg holds the list of available contexts
39	type ContextListMsg struct {
40		Contexts []string
41		Current  string
42	}
43	
44	// switchContext handles context switching with auto-creation.
45	//
46	// It settles the current view first, for the reason switchView does: a context
47	// switch rebuilds every view against a different file, so an uncommitted edit
48	// would be dropped — and dropped against the config it was *not* meant for.
49	func (a *App) switchContext(contextName string) tea.Cmd {
50		if cmd, ok := a.settleCurrentView(); !ok {
51			return cmd
52		}
53		a.switchingTo = contextName
54	
55		return func() tea.Msg {
56			log.Printf("Context switch requested: %s", contextName)
57	
58			cfg, created, err := loadOrCreateContext(contextName)
59			if err != nil {
60				return ContextSwitchErrorMsg{Error: err}
61			}
62	
63			// Each context gets its own store: the backend preference is per
64			// context because the configuration file is, and the secrets are keyed
65			// by context so two of them pointing at the same host stay separate.
66			secrets := credentials.Select(contextName, cfg.App.SecretBackend)
67			notices := credentials.MigrateLegacySecrets(secrets.Storage, contextName)
68	
69			backend, user := autoLoginForContext(contextName, cfg, secrets.Storage)
70	
71			log.Printf("Context switch successful: %s (created: %v, secrets: %s)", contextName, created, secrets.Backend)
72			return ContextSwitchCompleteMsg{
73				ContextName: contextName,
74				Config:      cfg,
75				Created:     created,
76				Forge:       backend,
77				GitLabUser:  user,
78				Secrets:     secrets,
79				Notices:     notices,
80			}
81		}
82	}
83	
84	// loadOrCreateContext validates the name, creates the context when it does not
85	// exist yet, loads its configuration and persists it as current.
86	func loadOrCreateContext(contextName string) (*config.Config, bool, error) {
87		if err := config.ValidateContextName(contextName); err != nil {
88			log.Printf("ERROR: Context validation failed: %v", err)
89			return nil, false, err
90		}
91	
92		exists, err := config.ContextExists(contextName)
93		if err != nil {
94			log.Printf("ERROR: Failed to check context existence: %v", err)
95			return nil, false, err
96		}
97	
98		created := false
99		if !exists {
100			log.Printf("Context '%s' does not exist, creating automatically", contextName)
101			if err := config.CreateContext(contextName); err != nil {
102				log.Printf("ERROR: Failed to create context '%s': %v", contextName, err)
103				return nil, false, err
104			}
105			created = true
106			log.Printf("Context '%s' created successfully", contextName)
107		}
108	
109		cfg, err := config.LoadContext(contextName)
110		if err != nil {
111			log.Printf("ERROR: Failed to load context '%s': %v", contextName, err)
112			return nil, created, err
113		}
114	
115		if err := config.SetCurrentContext(contextName); err != nil {
116			log.Printf("ERROR: Failed to persist context switch: %v", err)
117			return nil, created, err
118		}
119	
120		return cfg, created, nil
121	}
122	
123	// autoLoginForContext tries the new context's own credentials. A failure is not
124	// an error: the user is sent to the auth view instead.
125	func autoLoginForContext(contextName string, cfg *config.Config, storage credentials.Storage) (forge.Forge, forge.User) {
126		if cfg.Forge.URL == "" {
127			return nil, forge.User{}
128		}
129	
130		auth := session.NewAuth(storage)
131	
132		token, err := auth.LoadCredentials(cfg.Forge.URL)
133		if err != nil || token == "" {
134			return nil, forge.User{}
135		}
136	
137		result, err := auth.AuthenticateOnly(context.Background(), cfg.Forge.Type, cfg.Forge.URL, token)
138		if err != nil {
139			log.Printf("Auto-login failed for context '%s': %v", contextName, err)
140			return nil, forge.User{}
141		}
142		log.Printf("Auto-login successful for context '%s': %s", contextName, result.User.Username)
143		return result.Forge, result.User
144	}
145	
146	// listContexts retrieves available contexts
147	func (a *App) listContexts() tea.Cmd {
148		return func() tea.Msg {
149			log.Printf("Listing available contexts")
150			contexts, err := config.ListContexts()
151			if err != nil {
152				log.Printf("ERROR: Failed to list contexts: %v", err)
153				return ContextSwitchErrorMsg{Error: err}
154			}
155	
156			current, _ := config.GetCurrentContext()
157			if current == "" {
158				current = "default"
159			}
160	
161			log.Printf("Found %d contexts, current: %s", len(contexts), current)
162			return ContextListMsg{Contexts: contexts, Current: current}
163		}
164	}
165	
166	// handleContextSwitchComplete processes successful context switches
167	func (a *App) handleContextSwitchComplete(msg ContextSwitchCompleteMsg) (tea.Model, tea.Cmd) {
168		a.switchingTo = ""
169		a.config = msg.Config
170		a.currentContext = msg.ContextName
171		theme.SetGaugeGlyph(msg.Config.App.GaugeGlyph)
172		a.sharedState.Secrets = msg.Secrets
173		a.sharedState.SecretNotices = msg.Notices
174	
175		// Reset GitLab auth state — the new context has its own credentials
176		a.clearAuthenticated()
177	
178		// Apply auto-login result from the context switch if successful
179		var indexCmd tea.Cmd
180		if msg.Forge != nil {
181			indexCmd = a.setAuthenticated(msg.Forge, msg.GitLabUser)
182		} else {
183			// No credentials available — navigate to auth view for manual login
184			a.currentView = command.ViewGitAuth
185		}
186	
187		// The new context's tools may run from elsewhere: its views start from
188		// "not known yet" rather than from the previous context's answer.
189		a.forgetScanTools()
190	
191		// Reinitialize views with new config; auth state is already populated above
192		initCmd := a.reinitializeViews()
193	
194		// The rebuilt views know nothing of the work that is still running, and it
195		// did not stop: a run is stamped with the context it was started in and
196		// kept for the session (D8), so a switch changes which runs are relevant,
197		// never whether they exist. Telling the new views is the whole of it.
198		return a, tea.Batch(a.requestResize(), initCmd, a.jobsChanged(), a.restartMCPCmd(), a.syncProxyPortCmd(),
199			a.detectScanTools(), indexCmd)
200	}
201	
202	// handleContextList opens the picker with the cursor on the context in use, so
203	// enter is a no-op rather than a switch to whatever sorts first.
204	func (a *App) handleContextList(msg ContextListMsg) (tea.Model, tea.Cmd) {
205		a.showContextList = true
206		a.contextList = msg.Contexts
207		a.contextSelectedIdx = indexOf(msg.Contexts, msg.Current)
208		return a, nil
209	}
210	
211	// handleContextListKeyMsg handles key presses in the context selection overlay
212	func (a *App) handleContextListKeyMsg(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
213		switch msg.String() {
214		case "esc", "q":
215			a.showContextList = false
216		case "up":
217			a.contextSelectedIdx = max(a.contextSelectedIdx-1, 0)
218		case "down":
219			a.contextSelectedIdx = min(a.contextSelectedIdx+1, len(a.contextList)-1)
220		case "enter":
221			if len(a.contextList) > 0 {
222				a.showContextList = false
223				return a, a.switchContext(a.contextList[a.contextSelectedIdx])
224			}
225		}
226		return a, nil
227	}
228	
229	// renderContextListOverlay renders an overlay with the list of contexts
230	func (a *App) renderContextListOverlay() string {
231		return renderPickerOverlay("Select Context", a.contextList, a.currentContext, a.contextSelectedIdx)
232	}
233	
234	// renderContextSwitchingOverlay stands in for the interface while a switch
235	// loads, so the first views drawn after it are the new context's.
236	func (a *App) renderContextSwitchingOverlay() string {
237		return theme.OverlayBoxStyle().Render(theme.Bg("Switching to context " + a.switchingTo + "..."))
238	}
239	
240	// renderPickerOverlay draws the list overlays: a title, one entry per line, the
241	// entry in use marked and the highlighted one carrying the focus indicator.
242	func renderPickerOverlay(title string, entries []string, current string, selectedIdx int) string {
243		var b strings.Builder
244	
245		b.WriteString(theme.TitleStyle.Render(title) + "\n\n")
246	
247		for i, entry := range entries {
248			label := entry
249			if entry == current {
250				label += " (current)"
251			}
252			if i == selectedIdx {
253				b.WriteString(theme.KeyStyle.Render(theme.IconCircleSmall + " " + label))
254			} else {
255				b.WriteString(theme.Bg("  " + label))
256			}
257			b.WriteString("\n")
258		}
259	
260		return theme.OverlayBoxStyle().Render(b.String())
261	}
262	
263	// indexOf returns the position of want, or 0 when it is absent — the cursor has
264	// to land on a row that exists.
265	func indexOf(entries []string, want string) int {
266		for i, entry := range entries {
267			if entry == want {
268				return i
269			}
270		}
271		return 0
272	}
