14	// Entry is one command target with all its spellings.
15	type Entry struct {
16		Name        string
17		Aliases     []string
18		Description string
19		// Arg is the argument placeholder an action takes, e.g. "<name>"; empty
20		// when the entry takes none.
21		Arg  string
22		Kind EntryKind
23	}
24	
25	// Label is what a listing shows for the entry: the name, followed by its
26	// argument placeholder when it takes one.
27	func (e Entry) Label() string {
28		if e.Arg == "" {
29			return e.Name
30		}
31		return e.Name + " " + e.Arg
32	}
33	
34	// TakesArg reports whether the entry expects an argument.
35	func (e Entry) TakesArg() bool { return e.Arg != "" }
36	
37	// spec is a registry row: the public Entry plus what the parser resolves it to.
38	type spec struct {
39		Entry
40		view   ViewType    // KindView only
41		action CommandType // KindAction only
42	}
43	
44	// registry is the single source of every command spelling: parsing
45	// (viewNames, actionNames, actionAliases), completion and listings all derive
46	// from it. Views come first, then actions, each alphabetical by canonical name;
47	// aliases keep their declaration order. ViewViewer is deliberately absent, for
48	// the reason given on its declaration.
49	var registry = []spec{
50		// No one-letter alias for about: `a` is worth more than this view, which is
51		// opened once to read a version and not returned to.
52		{Entry{Name: "about", Aliases: []string{"version"}, Description: "Build version and where files are kept"}, ViewAbout, ""},
53		{Entry{Name: "agent-usage", Aliases: []string{"au"}, Description: "Claude Code sessions and token usage"}, ViewAgentUsage, ""},
54		{Entry{Name: "configuration", Aliases: []string{"config", "cfg"}, Description: "Settings of the current context"}, ViewConfiguration, ""},
55		{Entry{Name: "containers", Aliases: []string{"cont", "ct"}, Description: "Containers, metrics and logs"}, ViewContainers, ""},
56		{Entry{Name: "dashboard", Aliases: []string{"dash", "d"}, Description: "Code, health, host and Docker at a glance"}, ViewDashboard, ""},
57		{Entry{Name: "files", Aliases: []string{"fs"}, Description: "Browse the whole filesystem"}, ViewFiles, ""},
58		{Entry{Name: "git-auth", Aliases: []string{"ga"}, Description: "Sign in to your forge"}, ViewGitAuth, ""},
59		{Entry{Name: "git-explorer", Aliases: []string{"ge"}, Description: "Browse and clone forge projects"}, ViewGitExplorer, ""},
60		{Entry{Name: "jobs", Aliases: []string{"j"}, Description: "Long-running jobs started this session"}, ViewJobs, ""},
61		{Entry{Name: "netdiag", Aliases: []string{"net"}, Description: "Reachability, ports, interfaces, forwarding"}, ViewNetdiag, ""},
62		{Entry{Name: "oci-resources", Aliases: []string{"oci"}, Description: "Images, networks, volumes and registries"}, ViewOCIResources, ""},
63		{Entry{Name: "security", Aliases: []string{"sec"}, Description: "CVE, secret and license scans"}, ViewSecurity, ""},
64		{Entry{Name: "status", Aliases: []string{"s"}, Description: "HTTP, ICMP, DNS and SSL checks"}, ViewStatus, ""},
65		{Entry{Name: "templates", Aliases: []string{"tpl"}, Description: "Repository template catalog"}, ViewTemplates, ""},
66		{Entry{Name: "workspaces", Aliases: []string{"ws", "w"}, Description: "Local repositories and their Git state"}, ViewWorkspaces, ""},
67		{Entry{Name: "context", Aliases: []string{"ctx", "c"}, Description: "Switch or list contexts", Arg: "<name>", Kind: KindAction}, "", CommandContext},
68		{Entry{Name: "quit", Aliases: []string{"q"}, Description: "Exit DevDesk", Kind: KindAction}, "", CommandQuit},
69	}
70	
71	// Entries returns the ordered registry as a deep copy: callers may modify it
72	// freely.
73	func Entries() []Entry {
74		out := make([]Entry, len(registry))
75		for i, s := range registry {
76			out[i] = s.Entry
77			out[i].Aliases = append([]string(nil), s.Aliases...)
78		}
79		return out
80	}
81	
82	// buildViewNames derives the spelling-to-view map from the registry.
83	func buildViewNames() map[string]ViewType {
84		m := make(map[string]ViewType)
85		for _, s := range registry {
86			if s.Kind != KindView {
87				continue
88			}
89			m[s.Name] = s.view
90			for _, a := range s.Aliases {
91				m[a] = s.view
92			}
93		}
94		return m
95	}
96	
97	// buildActionNames derives the action-name map from the registry.
98	func buildActionNames() map[string]CommandType {
99		m := make(map[string]CommandType)
100		for _, s := range registry {
101			if s.Kind == KindAction {
102				m[s.Name] = s.action
103			}
104		}
105		return m
106	}
107	
108	// buildActionAliases derives the action alias-to-name map from the registry.
109	func buildActionAliases() map[string]string {
110		m := make(map[string]string)
111		for _, s := range registry {
112			if s.Kind != KindAction {
113				continue
114			}
115			for _, a := range s.Aliases {
116				m[a] = s.Name
117			}
118		}
119		return m
120	}
