1	package command
2	
3	import (
4		"cmp"
5		"reflect"
6		"slices"
7		"strings"
8		"unicode"
9	)
10	
11	// Stage says what the input is currently completing.
12	type Stage int
13	
14	const (
15		// StageCommand completes the command word.
16		StageCommand Stage = iota
17		// StageArgument completes the argument of a command that takes one.
18		StageArgument
19	)
20	
21	// ArgSuggestion is one candidate argument with an optional note.
22	type ArgSuggestion struct{ Value, Note string }
23	
24	// ArgProvider supplies argument candidates for one command. The prefix is
25	// passed raw: case is preserved (the provider decides how to compare) and
26	// trailing whitespace is trimmed. ready is false while the provider is still
27	// loading its candidates.
28	type ArgProvider interface {
29		SuggestArgs(prefix string) (args []ArgSuggestion, ready bool)
30	}
31	
32	// Suggestions is the result of one Suggest call.
33	type Suggestions struct {
34		Query   string
35		Stage   Stage
36		Entries []Entry
37		Total   int
38		Args    []ArgSuggestion
39		// ArgsReady is false while the argument provider is still loading, so the
40		// caller can tell "no candidates yet" from "no candidates".
41		ArgsReady bool
42	}
43	
44	// Ranks of a match, best first.
45	const (
46		rankExact       = iota // the word is the name or an alias
47		rankNamePrefix         // the word starts the canonical name
48		rankAliasPrefix        // the word starts an alias
49		rankNone
50	)
51	
52	// Suggester ranks registry entries against the input.
53	type Suggester struct {
54		entries   []Entry
55		providers map[string]ArgProvider
56	}
57	
58	// NewSuggester returns a Suggester over the registry.
59	func NewSuggester() *Suggester {
60		return &Suggester{entries: Entries(), providers: map[string]ArgProvider{}}
61	}
62	
63	// WithProvider registers the argument provider of a command and returns the
64	// suggester. The command is resolved like typed input, so an alias registers
65	// under the canonical name; an unknown command or a nil provider (including a
66	// typed nil pointer) is ignored.
67	func (s *Suggester) WithProvider(command string, p ArgProvider) *Suggester {
68		if p == nil {
69			return s
70		}
71		if v := reflect.ValueOf(p); v.Kind() == reflect.Pointer && v.IsNil() {
72			return s
73		}
74		if e, ok := s.exact(normalize(command)); ok {
75			s.providers[e.Name] = p
76		}
77		return s
78	}
79	
80	// Suggest ranks the entries for the input. Only the first word is ranked; once
81	// it names an entry that takes an argument and is followed by a space, the
82	// result switches to the argument stage.
83	func (s *Suggester) Suggest(input string) Suggestions {
84		raw := strings.TrimLeftFunc(strings.TrimPrefix(strings.TrimLeftFunc(input, unicode.IsSpace), ":"), unicode.IsSpace)
85		head, rest, hasRest := raw, "", false
86		if i := strings.IndexFunc(raw, unicode.IsSpace); i >= 0 {
87			head, rest, hasRest = raw[:i], strings.TrimSpace(raw[i:]), true
88		}
89		word := normalize(head)
90		out := Suggestions{Query: word, Total: len(s.entries)}
91	
92		if hasRest {
93			if e, ok := s.exact(word); ok && e.TakesArg() {
94				out.Stage = StageArgument
95				out.Entries = []Entry{e}
96				if p := s.providers[e.Name]; p != nil {
97					out.Args, out.ArgsReady = p.SuggestArgs(rest)
98				}
99				return out
100			}
101		}
102		out.Entries = s.rank(word)
103		return out
104	}
105	
106	// exact returns the entry whose name or alias is word.
107	func (s *Suggester) exact(word string) (Entry, bool) {
108		for _, e := range s.entries {
109			if matchRank(e, word) == rankExact {
110				return e, true
111			}
112		}
113		return Entry{}, false
114	}
115	
116	// rank returns the entries matching word, best rank first then by name; an
117	// empty word returns the registry in its own order.
118	func (s *Suggester) rank(word string) []Entry {
119		if word == "" {
120			return slices.Clone(s.entries)
121		}
122		type ranked struct {
123			e    Entry
124			rank int
125		}
126		var hits []ranked
127		for _, e := range s.entries {
128			if r := matchRank(e, word); r != rankNone {
129				hits = append(hits, ranked{e, r})
130			}
131		}
132		slices.SortStableFunc(hits, func(a, b ranked) int {
133			if c := cmp.Compare(a.rank, b.rank); c != 0 {
134				return c
135			}
136			return cmp.Compare(a.e.Name, b.e.Name)
137		})
138		out := make([]Entry, len(hits))
139		for i, h := range hits {
140			out[i] = h.e
141		}
142		return out
143	}
144	
145	// matchRank is the best rank of word against the entry's spellings.
146	func matchRank(e Entry, word string) int {
147		if e.Name == word || slices.Contains(e.Aliases, word) {
148			return rankExact
149		}
150		if strings.HasPrefix(e.Name, word) {
151			return rankNamePrefix
152		}
153		for _, a := range e.Aliases {
154			if strings.HasPrefix(a, word) {
155				return rankAliasPrefix
156			}
157		}
158		return rankNone
159	}
