1	// Package cmdsuggest renders the command-suggestion list shown under the
2	// command line (DEVDESK-89). Rendering is pure: state in, lines out.
3	package cmdsuggest
4	
5	import (
6		"fmt"
7		"strings"
8	
9		"github.com/charmbracelet/lipgloss"
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// MaxVisibleRows is the ceiling on suggestion rows shown at once.
17	const MaxVisibleRows = 8
18	
19	// Row is one suggestion; Current marks the view that is open now.
20	type Row struct {
21		Entry   command.Entry
22		Current bool
23	}
24	
25	// Frame selects the corners of the bottom rule.
26	type Frame int
27	
28	const (
29		// FrameJoined draws ├─┤ (the list sits above more viewport content).
30		FrameJoined Frame = iota
31		// FrameClosed draws └─┘.
32		FrameClosed
33	)
34	
35	// Input is everything Render needs.
36	type Input struct {
37		Rows    []Row
38		Total   int
39		Query   string
40		Cursor  int // -1 means no highlighted row
41		Offset  int
42		Notice  string
43		Width   int
44		Visible int
45		Frame   Frame
46	}
47	
48	// Layout holds column widths in cells.
49	type Layout struct{ Marker, Name, Alias, Desc int }
50	
51	// Pair is a foreground/background combination the list paints.
52	type Pair struct {
53		Name   string
54		Fg, Bg lipgloss.Color
55	}
56	
57	// Layout constants, in cells. The widths below are the whole grid: a line is
58	// a border, a one-cell margin, the columns, then fill up to the other border.
59	const (
60		margin        = 1
61		markerWidth   = 2
62		minDescWidth  = 20
63		minAliasWidth = 34 // narrowest terminal that still shows the alias column
64		wideWidth     = 100
65		aliasSep      = " · "
66		currentTag    = "(current)"
67		ellipsis      = "…"
68		// minRenderWidth is the narrowest width that holds a frame, a margin, a
69		// marker and one name cell.
70		minRenderWidth = 6
71	)
72	
73	// VisibleRows returns how many list rows fit: the matches, at least one row
74	// (the "no match" line), capped by MaxVisibleRows and by the usable height
75	// minus the filet.
76	func VisibleRows(matches, usable int) int {
77		return max(min(max(matches, 1), MaxVisibleRows, usable-1), 0)
78	}
79	
80	// Window returns the first visible row so that cursor stays in view. The
81	// window never wraps and, with no highlighted row, keeps the current offset.
82	func Window(cursor, offset, visible int) int {
83		offset = max(offset, 0)
84		if cursor < 0 || visible <= 0 {
85			return offset
86		}
87		switch {
88		case cursor < offset:
89			return cursor
90		case cursor >= offset+visible:
91			return cursor - visible + 1
92		}
93		return offset
94	}
95	
96	// Columns returns the column widths for a terminal width. Columns leave from
97	// the right: description first, then alias; the name alone remains.
98	func Columns(width int) Layout {
99		l := Layout{Marker: markerWidth}
100		if width < minAliasWidth {
101			l.Name = max(width-6, 1)
102			return l
103		}
104		l.Name, l.Alias = 15, 14
105		if width >= wideWidth {
106			l.Name, l.Alias = 18, 18
107		}
108		if desc := width - 2 - margin - l.Marker - l.Name - l.Alias; desc >= minDescWidth {
109			l.Desc = desc
110		}
111		return l
112	}
113	
114	// first returns the index of the first row drawn, kept inside the list.
115	func first(in Input) int {
116		return max(min(in.Offset, len(in.Rows)-max(in.Visible, 0)), 0)
117	}
118	
119	// FiletLabel returns the text of the bottom rule: the notice as a warning
120	// when there is one, otherwise the count with what scrolled out of view.
121	func FiletLabel(in Input) string {
122		if in.Notice != "" {
123			return theme.IconWarning + " " + in.Notice
124		}
125		in.Visible = max(in.Visible, 0)
126		label := fmt.Sprintf("%d of %d", len(in.Rows), in.Total)
127		if strings.TrimSpace(in.Query) == "" {
128			label = fmt.Sprintf("%d available", len(in.Rows))
129		}
130		start := first(in)
131		if above := start; above > 0 {
132			label += fmt.Sprintf(" · ▲ %d more", above)
133		}
134		if below := len(in.Rows) - start - in.Visible; below > 0 {
135			label += fmt.Sprintf(" · ▼ %d more", below)
136		}
137		return label
138	}
139	
140	// look is one foreground/background combination, read from the theme at call
141	// time so that a theme applied after start-up is honored.
142	type look struct {
143		name string
144		fg   lipgloss.Color
145		bg   lipgloss.Color
146		bold bool
147	}
148	
149	func (k look) style() lipgloss.Style {
150		return lipgloss.NewStyle().Foreground(k.fg).Background(k.bg).Bold(k.bold)
151	}
152	
153	func rowLook() look {
154		return look{name: "row", fg: theme.ColorText, bg: theme.ColorBackground}
155	}
156	
157	func highlightLook() look {
158		return look{name: "highlighted row", fg: theme.ColorText, bg: theme.ColorTableLineSelected, bold: true}
159	}
160	
161	func filetLook() look {
162		return look{name: "filet label", fg: theme.ColorText, bg: theme.ColorBackground}
163	}
164	
165	func warningLook() look {
166		return look{name: "filet warning", fg: theme.ColorFooterWarn, bg: theme.ColorBackground, bold: true}
167	}
168	
169	// Palette lists every text pair the list paints, for the contrast test. The
170	// frame characters are decoration and carry no information, so they are not
171	// listed.
172	func Palette() []Pair {
173		var out []Pair
174		for _, k := range []look{rowLook(), highlightLook(), filetLook(), warningLook()} {
175			out = append(out, Pair{Name: k.name, Fg: k.fg, Bg: k.bg})
176		}
177		return out
178	}
179	
180	// Render returns Visible list rows followed by the bottom rule, each exactly
181	// Width cells wide. Every line is assembled from separately styled segments;
182	// no already-styled text is ever cut.
183	func Render(in Input) []string {
184		in.Visible = max(in.Visible, 0)
185		if in.Width < minRenderWidth {
186			return degenerate(in)
187		}
188		inner := max(in.Width-2, 0)
189		layout := Columns(in.Width)
190		border := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
191		side := border.Render("│")
192	
193		lines := make([]string, 0, in.Visible+1)
194		if len(in.Rows) == 0 {
195			for i := 0; i < in.Visible; i++ {
196				body := theme.EmptyLineBg(inner)
197				if i == 0 {
198					body = row(noMatchText(in.Query), layout, inner, false)
199				}
200				lines = append(lines, side+body+side)
201			}
202		} else {
203			start := first(in)
204			for i := 0; i < in.Visible; i++ {
205				idx := start + i
206				if idx >= len(in.Rows) {
207					lines = append(lines, side+theme.EmptyLineBg(inner)+side)
208					continue
209				}
210				lines = append(lines, side+row(columnsOf(in.Rows[idx], layout), layout, inner, idx == in.Cursor)+side)
211			}
212		}
213		return append(lines, filet(in, inner, border))
214	}
215	
216	// degenerate renders the lines of a terminal too narrow for a frame: blank
217	// background lines and a bare rule, each exactly Width cells (possibly zero).
218	func degenerate(in Input) []string {
219		w := max(in.Width, 0)
220		lines := make([]string, 0, in.Visible+1)
221		for i := 0; i < in.Visible; i++ {
222			lines = append(lines, theme.EmptyLineBg(w))
223		}
224		rule := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
225		return append(lines, rule.Render(strings.Repeat("─", w)))
226	}
227	
228	// cells is the plain text of each column of one row.
229	// A message spans every column.
230	type cells struct{ name, alias, desc, message string }
231	
232	func noMatchText(query string) cells {
233		return cells{message: fmt.Sprintf("No match for %q", query)}
234	}
235	
236	// columnsOf returns the plain text of a row for a layout. The current marker
237	// leads the description, or stands in for the aliases when the description
238	// is hidden; it is dropped when neither column exists.
239	func columnsOf(r Row, l Layout) cells {
240		c := cells{
241			name:  r.Entry.Label(),
242			alias: strings.Join(r.Entry.Aliases, aliasSep),
243			desc:  r.Entry.Description,
244		}
245		if r.Current {
246			switch {
247			case l.Desc > 0:
248				c.desc = strings.TrimSpace(currentTag + " " + c.desc)
249			case l.Alias > 0:
250				c.alias = currentTag
251			}
252		}
253		return c
254	}
255	
256	// fit truncates plain text to leave one cell of air inside its column and
257	// pads it to the full width.
258	func fit(text string, width int) string {
259		if width <= 0 {
260			return ""
261		}
262		if lipgloss.Width(text) > width-1 {
263			text = ansi.Truncate(text, max(width-1, 1), ellipsis)
264		}
265		return text + strings.Repeat(" ", max(width-lipgloss.Width(text), 0))
266	}
267	
268	// row assembles one list line from styled segments, filled up to inner cells.
269	// A highlighted row fills with its own background so it reaches the border.
270	func row(c cells, l Layout, inner int, highlighted bool) string {
271		k, marker := rowLook(), strings.Repeat(" ", markerWidth)
272		if highlighted {
273			k, marker = highlightLook(), theme.IconCircleSmall+" "
274		}
275		st := k.style()
276		body := fit(c.name, l.Name) + fit(c.alias, l.Alias) + fit(c.desc, l.Desc)
277		if c.message != "" {
278			body = fit(c.message, max(inner-margin-markerWidth, 0))
279		}
280		plain := strings.Repeat(" ", margin) + marker + body
281		if w := lipgloss.Width(plain); w < inner {
282			plain += strings.Repeat(" ", inner-w)
283		}
284		return st.Render(plain)
285	}
286	
287	// filet builds the bottom rule with its label.
288	func filet(in Input, inner int, border lipgloss.Style) string {
289		left, right := "├", "┤"
290		if in.Frame == FrameClosed {
291			left, right = "└", "┘"
292		}
293		k := filetLook()
294		if in.Notice != "" {
295			k = warningLook()
296		}
297		label := ansi.Truncate(FiletLabel(in), max(inner-3, 0), ellipsis)
298		dashes := max(inner-2-lipgloss.Width(label)-1, 0)
299		return border.Render(left+"─ ") + k.style().Render(label) +
300			border.Render(" "+strings.Repeat("─", dashes)+right)
301	}
