	a := commanding(t, &fakeView{})
	typeCommand(t, a, "ctx work")
	press(t, a, "tab")

	if got := a.commandInput.Value(); got != "ctx work" {
		t.Errorf("tab rewrote the argument line to %q", got)
	}
}

